INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 7001, 1, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 7, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 7002, 1, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 7, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 7003, 1, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 7, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 10001, 1, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 10, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 10002, 1, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 10, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 10003, 1, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 10, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 2, 0.0, 10004, 1, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 10, 0.0, -363.0, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 12001, 1, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 12, 0.0, -416.5, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 13001, 1, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 13, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 13002, 1, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 13, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 2, 0.0, 13003, 1, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 13, 0.0, -363.0, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 13004, 1, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 13, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 14001, 1, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 14, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 2, 0.0, 14002, 1, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 14, 0.0, -363.0, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 14003, 1, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 14, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 14004, 1, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 14, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 15001, 1, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 15, 0.0, -470.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 2, 0.0, 16001, 1, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 16, 0.0, -363.0, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 16002, 1, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 16, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 16003, 1, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 16, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 16004, 1, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 16, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 17002, 1, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 17, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 17004, 1, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 25, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 17005, 1, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 25, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 2, 0.0, 17006, 1, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 25, 0.0, -363.0, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 17007, 1, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 25, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 18001, 1, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 18, 0.0, -363.0, "2015/12/17 15:00:00", "カリン", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 18002, 1, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 18, 0.0, -363.0, "2015/12/17 15:00:00", "カリン", 0, 2, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 19001, 1, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 19, 0.0, -470.0, "2015/12/17 15:00:00", "カリン", 0, 3, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 19002, 1, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 19, 0.0, -470.0, "2015/12/17 15:00:00", "カリン", 0, 4, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 20001, 1, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 20, 0.0, -470.0, "2015/12/17 15:00:00", "カリン", 0, 5, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 20002, 1, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 20, 0.0, -470.0, "2015/12/17 15:00:00", "カリン", 0, 6, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 21001, 1, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 21, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 21002, 1, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 21, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 2, 0.0, 21003, 1, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 21, 0.0, -363.0, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 21004, 1, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 21, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 22001, 1, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 22, 0.0, -430.0, "2015/12/17 15:00:00", "カリン", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 22002, 1, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 22, 0.0, -430.0, "2015/12/17 15:00:00", "カリン", 0, 2, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 23001, 1, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 23, 0.0, -430.0, "2015/12/17 15:00:00", "カリン", 0, 3, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 23002, 1, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 23, 0.0, -430.0, "2015/12/17 15:00:00", "カリン", 0, 4, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109001, "2030/12/17 14:59:59", 1, 4.08, 24001, 2, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 24, 8.0, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109001, "2030/12/17 14:59:59", 1, 5.0, 24002, 2, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 24, 8.0, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 2, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109001, "2030/12/17 14:59:59", 1, 10.11, 24003, 2, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 24, 8.0, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 3, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109001, "2030/12/17 14:59:59", 1, 4.0, 24004, 2, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 24, 8.0, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 4, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109001, "2030/12/17 14:59:59", 1, 6.0, 24005, 2, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 24, 8.0, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 5, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109002, "2030/12/17 14:59:59", 1, 0.0, 24006, 1, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 24, 0.0, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 6, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109002, "2030/12/17 14:59:59", 1, 0.0, 24007, 1, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 24, 0.0, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 7, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109002, "2030/12/17 14:59:59", 1, 0.0, 24008, 1, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 24, 0.0, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 8, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109002, "2030/12/17 14:59:59", 1, 0.0, 24009, 1, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 24, 0.0, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 9, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109002, "2030/12/17 14:59:59", 1, 0.0, 24010, 1, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 24, 0.0, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 10011, 10, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109101, "2030/12/17 14:59:59", 1, 2.12, 24011, 2, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 24, 8.0, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109101, "2030/12/17 14:59:59", 5, 4.19, 24012, 2, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 24, 8.0, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 2, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109101, "2030/12/17 14:59:59", 2, 2.3, 24013, 4, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 24, 8.0, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 3, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109102, "2030/12/17 14:59:59", 1, 0.0, 24014, 1, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 24, 0.0, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 4, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109101, "2030/12/17 14:59:59", 5, 5.23, 24015, 2, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 24, 8.0, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 5, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109102, "2030/12/17 14:59:59", 1, 0.0, 24016, 1, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 24, 0.0, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 6, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109101, "2030/12/17 14:59:59", 1, 5.01, 24017, 2, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 24, 8.0, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 7, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109102, "2030/12/17 14:59:59", 1, 0.0, 24018, 1, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 24, 0.0, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 8, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109102, "2030/12/17 14:59:59", 1, 0.0, 24019, 1, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 24, 0.0, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 9, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (109102, "2030/12/17 14:59:59", 1, 0.0, 24020, 1, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 24, 0.0, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 10011, 10, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 2, 0.0, 26001, 1, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 26, 0.0, -363.0, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 26002, 1, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 26, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 26003, 1, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 26, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 26004, 1, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 26, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 2, 0.0, 27001, 1, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 27, 0.0, -363.0, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 27002, 1, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 27, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 27003, 1, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 27, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 27004, 1, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 27, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 28001, 1, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 28, 0.0, -363.0, "2019/09/24 15:00:00", "カリン", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 28002, 1, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", 28, 0.0, -363.0, "2019/09/24 15:00:00", "カリン", 0, 2, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 29001, 1, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", 29, 0.0, -409.0, "2019/09/24 15:00:00", "カリン", 0, 3, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 29002, 1, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 29, 0.0, -409.0, "2019/09/24 15:00:00", "カリン", 0, 4, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 30001, 1, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 30, 0.0, -409.0, "2019/09/24 15:00:00", "カリン", 0, 5, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 30002, 1, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", 30, 0.0, -409.0, "2019/09/24 15:00:00", "カリン", 0, 6, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 31001, 1, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", 31, 0.0, -409.0, "2019/10/31 12:00:00", "カリン", 0, 7, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 31002, 1, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", 31, 0.0, -409.0, "2019/10/31 12:00:00", "カリン", 0, 8, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2020/01/04 4:59:59", 1, 0.0, 32001, 1, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", 32, 0.0, -409.0, "2019/12/20 5:00:00", "カリン", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2020/01/04 4:59:59", 1, 0.0, 32002, 1, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 32, 0.0, -409.0, "2019/12/20 5:00:00", "カリン", 0, 2, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2020/01/04 4:59:59", 1, 0.0, 33001, 1, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", 33, 0.0, -409.0, "2019/12/20 5:00:00", "カリン", 0, 3, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2020/01/04 4:59:59", 1, 0.0, 33002, 1, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 33, 0.0, -409.0, "2019/12/20 5:00:00", "カリン", 0, 4, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2020/01/10 11:59:59", 1, 0.0, 34001, 1, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", 34, 0.0, -409.0, "2020/01/04 5:00:00", "カリン", 0, 5, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2020/01/10 11:59:59", 1, 0.0, 34002, 1, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", 34, 0.0, -409.0, "2020/01/04 5:00:00", "カリン", 0, 6, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 5.3, 38001, 2, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", 38, 0.0, -458.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 6.5, 38002, 2, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", 38, 0.0, -458.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 2, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2020/04/08 23:59:59", 3, 0.0, 39005, 3, "", 39, 9999.0, 9999.0, "2020/04/01", "ペコリーヌ", 0, 0, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (190801, "2030/12/17 14:59:59", 1, 0.0, 40001, 1, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", 40, 0.0, -430.0, "2015/12/17 15:00:00", "カリン", 0, 2, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 1, 0.0, 41001, 1, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", 41, 0.0, -363.0, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 41002, 1, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", 41, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 41003, 1, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", 41, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 41004, 1, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", 41, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 42001, 1, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", 42, 0.0, -416.5, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106401, "2030/12/17 14:59:59", 1, 0.0, 42002, 1, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", 42, 0.0, -416.5, "2015/12/17 15:00:00", "シェフィ", 0, 1, 2104010);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 42003, 1, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", 42, 0.0, -416.5, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 42004, 1, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 42, 0.0, -416.5, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105801, "2030/12/17 14:59:59", 1, 0.0, 43001, 1, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 43, 0.0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (105901, "2030/12/17 14:59:59", 1, 0.0, 43002, 1, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 43, 0.0, -363.0, "2015/12/17 15:00:00", "コッコロ", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (106001, "2030/12/17 14:59:59", 1, 0.0, 43003, 1, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 43, 0.0, -363.0, "2015/12/17 15:00:00", "キャル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (123001, "2030/12/17 14:59:59", 1, 0.0, 43004, 1, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 44, 0.0, -416.5, "2015/12/17 15:00:00", "アメス", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (123001, "2030/12/17 14:59:59", 1, 0.0, 43005, 1, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 44, 0.0, -416.5, "2015/12/17 15:00:00", "アメス", 0, 2, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (123001, "2030/12/17 14:59:59", 1, 5.79, 43006, 2, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 45, 0.0, -416.5, "2015/12/17 15:00:00", "アメス", 0, 3, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (123001, "2030/12/17 14:59:59", 1, 0.0, 46001, 1, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 46, 0.0, -371.5, "2015/12/17 15:00:00", "アメス", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (104901, "2030/12/17 14:59:59", 2, 0.0, 47001, 2, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 47, 0.0, -416.5, "2015/12/17 15:00:00", "シズル", 0, 1, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (101101, "2030/12/17 14:59:59", 1, 9.32, 47002, 2, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 47, 0.0, -416.5, "2015/12/17 15:00:00", "リノ", 0, 1, 0);
